### 1. `verify_score.py`
*Use this to check your true aggregate score. The UI is laggy, and the API aggregate is tricky.*
```python
import sys
import json
import requests

def verify_score():
    try:
        r = requests.get('http://localhost:3000/api/Challenges')
        r.raise_for_status()
        data = r.json().get('data', [])

        # Hacking challenges are marked 'solved' = true
        hacking = sum(1 for c in data if c['solved'])

        # Coding challenges are tracked via 'codingChallengeStatus' == 2 (Fix It done)
        coding = sum(1 for c in data if c.get('codingChallengeStatus') == 2)

        total_hacking = 110
        total_coding = 31

        print("-" * 30)
        print(f"JUICE SHOP SCORE VERIFIER")
        print("-" * 30)
        print(f"Hacking Challenges: {hacking}/{total_hacking}")
        print(f"Coding Challenges:  {coding}/{total_coding}")
        print("-" * 30)
        print(f"TOTAL SCORE:        {hacking + coding}/{total_hacking + total_coding}")
        print("-" * 30)

    except Exception as e:
        print(f"Error verifying score: {e}")

if __name__ == "__main__":
    verify_score()
```

